<template>
<div class="studio" :class="{'focus-mode':focus}">
 <section class="lesson">
  <nav class="lesson-tabs" aria-label="Session Hub tools">
   <button v-if="host" :class="{active:active?.payload.mode==='whiteboard'}" @click="whiteboard">Whiteboard</button>
   <button @click="panel='materials'">Worksheets &amp; resources</button><button v-if="host" @click="panel='activity'">Activities &amp; progress</button>
   <span>{{host?'Tutor view':'Learner view'}}</span><button :aria-pressed="focus" @click="focus=!focus">{{focus?'Show panels':'Focus lesson'}}</button>
  </nav>
  <p v-if="error" role="alert">{{error}} <button v-if="failed" @click="retry">Retry saved change</button><button v-else @click="refresh">Reconnect</button></p>
  <p v-if="notice" class="notice" role="status">{{notice}}</p>
  <div v-if="editorId||viewingSharedId" class="stage"><button class="return" @click="editorId=null;viewingSharedId=null">Return to shared lesson</button><TutoringWorksheet :key="'edit-'+(editorId||viewingSharedId)" :version-id="editorId||viewingSharedId" :host="host" :closed="closed" :request="request" :learning-context="learningContext" @changed="loadMaterials" @shared="editorId=null;refresh()"/></div>
  <div v-else-if="active?.payload.mode==='whiteboard'" class="stage board-stage" :inert="closed||undefined">
   <SharedTeachingBoard :key="active.payload.boardId||active.id" :board-id="Number(active.payload.boardId||active.id)" :events="events" :host="host" :actor="actor" :save="save" :busy="saving||closed" :rate-activity="rateActivity" :generate="generateQuestion" :learning-context="learningContext" :materials="materials" :read-material="readMaterial"/>
  </div>
  <div v-else-if="active?.payload.mode==='worksheet'" class="stage"><TutoringWorksheet :key="'shared-'+active.payload.versionId" :version-id="Number(active.payload.versionId)" :host="host" :closed="closed" :request="request" :learning-context="learningContext" @changed="loadMaterials" @shared="refresh"/></div>
  <div v-else class="ready-stage"><div class="ready-icon">▤</div><h2>{{host?'Ready for today’s learning':'You’re in the right place'}}</h2><p>{{host?'Open a whiteboard, prepare a worksheet, or choose a reviewed activity. Your lesson stays with this appointment.':'Your tutor will share a whiteboard or worksheet here. Your learning stays together in this session.'}}</p><button v-if="host&&!closed" class="primary" @click="whiteboard">Open shared whiteboard</button><span v-else>{{closed?'This session has ended.':'Waiting for your tutor to share'}}</span></div>
 </section>
 <aside class="studio-panel">
  <nav class="panel-tabs" aria-label="Session panels"><button :class="{active:panel==='learning'}" @click="panel='learning'">Learning</button><button :class="{active:panel==='materials'}" @click="panel='materials'">Materials</button><button v-if="host" :class="{active:panel==='notes'}" @click="panel='notes'">Notes</button><button :class="{active:panel==='chat'}" @click="panel='chat'">Chat</button></nav>
  <section v-if="panel==='learning'" class="panel-content"><h2>{{host?'Learning focus':'My learning'}}</h2><slot name="learning"/><h3>Session materials</h3><p v-if="!materials.length">Your tutor will prepare materials here.</p><article v-for="m in materials" :key="m.id" class="resource"><strong>{{m.title}}</strong><small>{{m.versions.length?'Worksheet prepared':'Source document'}}</small></article></section>
  <section v-if="panel==='materials'" class="panel-content"><h2>{{host?'Worksheets & resources':'Shared materials'}}</h2><p>{{host?'Prepare privately, review, then share only the selected version.':'Only materials your tutor has shared with you appear here.'}}</p>
   <label v-if="host&&!closed" class="upload">Upload PDF or image<input type="file" accept="application/pdf,image/png,image/jpeg" :disabled="uploading" @change="upload"/></label><p v-if="uploading" role="status">Saving your source document…</p>
   <section v-if="host" class="library-summary"><h3>Resource library</h3><router-link :to="(route.params.organizationSlug?'/'+route.params.organizationSlug:'')+'/tutoring-library'">Manage private drafts / staff publishing</router-link><article v-for="r in library" :key="r.id" class="resource"><strong>{{r.title}}</strong><small>{{r.status}} · {{r.grade}}</small><button :disabled="uploading" @click="useResource(r)">Prepare for this student</button></article></section>
   <p v-if="!materials.length">No {{host?'prepared':'shared'}} worksheets yet.</p>
   <article v-for="m in materials" :key="m.id" class="resource"><strong>{{m.title}}</strong><div v-for="v in m.versions" :key="v.id" class="version"><span>v{{v.version}} · {{v.status}}{{v.shared?' · Shared':''}}</span><button v-if="host" @click="editorId=v.id">Review / open</button><button v-if="host&&v.shared&&!closed" @click="unshare(v.id)">Stop sharing</button><button v-if="!host" @click="openShared(v.id)">Open worksheet</button></div><template v-if="host&&!closed"><button v-if="!m.versions.length" @click="blank(m)">Add answer areas</button><button :disabled="drafting===m.id" @click="draft(m)">{{drafting===m.id?'Preparing draft…':'Draft answer areas with AI'}}</button></template></article>
  </section>
  <section v-if="panel==='notes'" class="panel-content"><h2>Private notes &amp; summary</h2><slot name="notes"/></section>
  <section v-if="panel==='activity'" class="panel-content"><h2>Activities &amp; progress</h2><p>Rate each shared item from observed work. AI drafts and family observations do not advance a learning goal.</p><slot name="progress"/><button @click="loadProgress">Refresh progress review</button><article v-for="s in suggestions" :key="s.id" class="resource"><strong>{{s.title}}</strong><p>{{s.previousStatus}} → {{s.recommendedStatus}}</p><p>{{s.reason}}</p><small>{{s.measureCount}} observed measures · {{s.confidence}} confidence</small><button @click="decideProgress(s,'approve')">Approve goal progress</button><button @click="decideProgress(s,'dismiss')">Keep current goal level</button></article><article v-for="item in activities" :key="item.id" class="resource"><strong>{{item.payload.prompt||item.payload.title||item.payload.mode}}</strong><small v-if="item.payload.skill">{{item.payload.skill}} · {{item.payload.grade}}</small><label>Session observation<select :disabled="!!reviewed(item.id)" @change="review(item.id,$event.target.value)"><option value="">{{reviewed(item.id)||'Choose a rating'}}</option><option value="emerging">1 · Emerging</option><option value="developing">2 · Developing</option><option value="nearly_secure">3 · Nearly secure</option><option value="secure">4 · Secure independently</option><option value="not_observed">Not assessed / demonstrated</option></select></label></article><p v-if="!activities.length">Shared questions and resources will appear here.</p></section>
  <section v-if="panel==='chat'" class="panel-content"><h2>Session chat</h2><p class="muted">Shared with the people admitted to this appointment.</p><article v-for="m in chats" :key="m.id" class="chat"><small>{{m.role==='provider'?'Tutor':'Family'}}</small><p>{{m.payload.text}}</p></article><form @submit.prevent="sendChat"><label>Message<input v-model="chat" maxlength="4000" :disabled="closed"/></label><button :disabled="closed||!chat.trim()||saving">Send</button></form></section>
 </aside>
</div>
</template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import {useRoute} from 'vue-router';
import SharedTeachingBoard from '../meetings/SharedTeachingBoard.vue';
import TutoringWorksheet from './TutoringWorksheet.vue';
const route=useRoute(),library=ref([]),suggestions=ref([]);
const props=defineProps({host:Boolean,closed:Boolean,request:Function,workspaceRequest:Function,learningContext:Object,rateActivity:Function,generateQuestion:Function,readMaterial:Function});
const events=ref([]),actor=ref(''),panel=ref('learning'),focus=ref(false),error=ref(''),notice=ref(''),saving=ref(false),failed=ref(null),materials=ref([]),editorId=ref(null),viewingSharedId=ref(null),uploading=ref(false),drafting=ref(null),chat=ref('');
let cursor=0,disposed=false,poll,reading=false,writes=Promise.resolve();
const active=computed(()=>events.value.filter(e=>e.type==='share').at(-1));
const chats=computed(()=>events.value.filter(e=>e.type==='chat'));
const activities=computed(()=>events.value.filter(e=>e.type==='board_prompt'||e.type==='share'&&!e.payload.boardId&&!['video','whiteboard'].includes(e.payload.mode)));
const reviewed=id=>events.value.filter(e=>e.type==='board_review'&&Number(e.payload.targetId)===id).at(-1)?.payload.rating;
function merge(items){const map=new Map(events.value.map(e=>[e.id,e]));for(const e of items)map.set(e.id,e);events.value=[...map.values()].sort((a,b)=>a.id-b.id);}
async function refresh(){if(disposed||reading)return;reading=true;try{let more=true;while(more&&!disposed){const d=await props.workspaceRequest('?afterId='+cursor);if(disposed)return;actor.value=d.actor;merge(d.artifacts||[]);cursor=d.nextCursor||cursor;more=d.hasMore===true;}if(!failed.value)error.value='';}catch(e){if(!disposed)error.value=e.response?.data?.error?.message||'The lesson connection was interrupted. Your local changes are retained.';}finally{reading=false;}}
function save(type,payload,requestId=crypto.randomUUID()){
 const body={type,payload,requestId};
 const operation=writes.catch(()=>{}).then(async()=>{if(failed.value)throw new Error('Retry the previous change before continuing.');saving.value=true;try{const result=await props.workspaceRequest('',{method:'POST',body});merge([result.artifact]);error.value='';return result;}catch(e){failed.value=body;error.value=e.response?.data?.error?.message||'Your change was not saved. Retry before leaving this lesson.';throw e;}finally{saving.value=false;}});
 writes=operation;return operation;
}
async function retry(){const f=failed.value;if(!f)return;failed.value=null;try{await save(f.type,f.payload,f.requestId);}catch{}}
async function whiteboard(){editorId.value=null;if(active.value?.payload.mode==='whiteboard')return;const last=events.value.filter(e=>e.type==='share'&&e.payload.mode==='whiteboard').at(-1);try{await save('share',{mode:'whiteboard',title:'Shared whiteboard',...(last?{boardId:last.payload.boardId||last.id}:{})});}catch{}}
async function loadMaterials(){try{const d=await props.request('/studio/materials');if(!disposed)materials.value=d.materials;}catch(e){error.value=e.response?.data?.error?.message||'Materials could not be loaded.';}}
async function blank(m){try{const v=await props.request('/studio/materials/'+m.id+'/versions','post',{instructions:'',questions:[]});editorId.value=v.id;await loadMaterials();}catch(e){error.value=e.response?.data?.error?.message||e.message;}}
async function upload(e){const file=e.target.files[0];if(!file)return;uploading.value=true;error.value='';try{const form=new FormData();form.append('file',file);form.append('title',file.name);const d=await props.request('/studio/materials','post',form);await loadMaterials();await blank(d.material);notice.value='Source saved privately. Add and review answer areas before sharing.';}catch(err){error.value=err.response?.data?.error?.message||'The upload was not saved. Choose the file and retry.';}finally{uploading.value=false;e.target.value='';}}
async function draft(m){drafting.value=m.id;error.value='';try{const v=await props.request('/studio/materials/'+m.id+'/draft','post',{}, {timeout:120000});editorId.value=v.id;await loadMaterials();notice.value='AI draft ready for tutor review. It has not been shared.';}catch(e){error.value=e.response?.data?.error?.message||'AI drafting failed. Your source is retained; you can add answer areas manually.';}finally{drafting.value=null;}}
async function unshare(id){try{await props.request('/studio/versions/'+id+'/share','post',{share:false});if(active.value?.payload.versionId===id)await whiteboard();await loadMaterials();}catch(e){error.value=e.response?.data?.error?.message||e.message;}}
async function openShared(id){viewingSharedId.value=id;}
async function review(id,rating){if(!rating)return;try{await props.rateActivity(id,rating);await refresh();notice.value='Observation saved with this session.';}catch(e){error.value=e.response?.data?.error?.message||e.message;}}
async function sendChat(){const value=chat.value.trim();if(!value)return;try{await save('chat',{text:value});chat.value='';}catch{}}
async function tick(){await refresh();if(!disposed)poll=setTimeout(tick,1800);}
async function loadLibrary(){if(!props.host)return;try{const d=await props.request('/studio/library');library.value=d.resources;}catch(e){error.value=e.response?.data?.error?.message||e.message;}}
async function useResource(r){uploading.value=true;try{const d=await props.request('/studio/library/'+r.id+'/use','post');editorId.value=d.version.id;await loadMaterials();notice.value='Private session copy prepared. Review before sharing.';}catch(e){error.value=e.response?.data?.error?.message||e.message;}finally{uploading.value=false;}}
async function loadProgress(){if(!props.host)return;try{const d=await props.request('/studio/progress');suggestions.value=d.suggestions;}catch(e){error.value=e.response?.data?.error?.message||e.message;}}
async function decideProgress(s,decision){try{await props.request('/studio/progress/'+s.id,'post',{decision});await loadProgress();notice.value=decision==='approve'?'Goal progress approved and recorded.':'Current goal level retained.';}catch(e){error.value=e.response?.data?.error?.message||e.message;}}
onMounted(()=>{tick();loadMaterials();loadLibrary();});onBeforeUnmount(()=>{disposed=true;clearTimeout(poll);});
defineExpose({whiteboard,showMaterials:()=>panel.value='materials',showChat:()=>panel.value='chat',showNotes:()=>panel.value='notes'});
</script>
<style scoped>
.studio{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:12px;min-height:0}.lesson{background:white;border:1px solid #c8d8e2;border-radius:14px;overflow:hidden;min-width:0;display:flex;flex-direction:column;min-height:calc(100dvh - 200px)}.lesson-tabs{display:flex;align-items:center;gap:3px;border-bottom:1px solid #d6e2e9;padding:7px;background:#f6f9fb;flex-wrap:wrap}.lesson-tabs span{margin-left:auto;font-size:11px;color:#567081}.studio button{font:inherit;font-size:12px;border:1px solid #c9d9e2;border-radius:8px;background:white;color:#163b55;padding:8px 10px;cursor:pointer}.studio button:hover{background:#e9f5f1}.studio button:focus-visible{outline:3px solid #2c8794;outline-offset:2px}.studio button:disabled{opacity:.5;cursor:default}.studio .active{background:#c5efe2;border-color:#72b6a6}.stage{min-height:0;flex:1}.board-stage{padding:8px}.board-stage :deep(.teaching-board){border:0}.board-stage :deep(.sheet){height:clamp(350px,calc(100dvh - 340px),850px);aspect-ratio:auto}.board-stage :deep(.board-bar){font-size:12px;gap:7px;padding:7px 0}.board-stage :deep(.board-bar input[type=color]){width:32px;height:30px;padding:2px;border:1px solid #b9ccd6;border-radius:6px;background:white}.board-stage :deep(.question .rating){display:grid;grid-template-columns:1fr;gap:5px;font-size:11px;color:#4d697a}.board-stage :deep(.question .rating select){font:inherit;font-size:12px;min-height:30px;padding:5px 8px;border:1px solid #bed1dc;background:#f5fafb;border-radius:6px;color:#163f57}.board-stage :deep(.question){padding:12px;gap:8px}.board-stage :deep(.question p){margin:4px 0;white-space:pre-wrap}.ready-stage{display:flex;flex:1;min-height:440px;align-items:center;justify-content:center;flex-direction:column;padding:32px;text-align:center;background:radial-gradient(#dae6e9 1px,transparent 1px) white;background-size:18px 18px}.ready-icon{font-size:65px;color:#488b85}.ready-stage h2{font-size:clamp(23px,2.5vw,36px);letter-spacing:-.035em;margin:16px 0}.ready-stage p{max-width:45ch;line-height:1.7;color:#4a6575}.ready-stage span{color:#426675;background:#e4f5ee;padding:12px 20px;border-radius:30px}.studio .primary{background:#153c5d;color:white;padding:12px 18px}.studio-panel{min-width:0;max-height:calc(100dvh - 185px);overflow:auto;background:white;border:1px solid #c8d8e2;border-radius:14px}.panel-tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:2px;padding:7px;position:sticky;top:0;background:white;z-index:2}.panel-tabs button{padding:8px 3px;font-size:11px}.panel-content{padding:6px 14px 18px}.panel-content h2{font-size:17px;margin:14px 0}.panel-content h3{font-size:14px;color:#31586b}.panel-content>p{font-size:13px;line-height:1.6;color:#526d7c}.resource{border:1px solid #d3e2e9;border-radius:9px;padding:12px;margin:10px 0;background:#f9fbfc;font-size:13px}.resource strong,.resource small{display:block;overflow-wrap:anywhere}.resource small{margin:5px 0;color:#537480}.resource button{margin:5px 3px 0 0;font-size:11px}.version{border-top:1px solid #deeaee;margin-top:8px;padding-top:5px}.version span{display:block;font-size:11px}.studio label{display:grid;gap:6px;font-size:12px;margin:12px 0}.studio input,.studio select{box-sizing:border-box;width:100%;border:1px solid #bdcfdc;border-radius:7px;padding:9px;background:white;color:#173b52;font:inherit}.upload{border:1px dashed #67a798;padding:12px;color:#1f6d60;border-radius:8px}.upload input{padding:0;border:0;font-size:11px}.chat{background:#edf5f7;padding:10px;border-radius:9px;margin:8px 0;overflow-wrap:anywhere}.chat p{white-space:pre-wrap}.chat small{color:#4c7080}.studio [role=alert]{color:#a42942;padding:8px 12px}.notice{font-size:12px;padding:8px 12px;color:#226e5d;background:#e9f7ef}.return{margin:8px}.focus-mode{grid-template-columns:minmax(0,1fr)}.focus-mode .studio-panel{display:none}@media(max-width:1200px){.studio{grid-template-columns:minmax(0,1fr) 250px}}@media(max-width:950px){.studio{display:flex;flex-direction:column}.studio-panel{max-height:none}.lesson{min-height:60dvh}.ready-stage{min-height:320px}.panel-tabs{grid-template-columns:repeat(4,1fr)}}
</style>
